import json
import csv
import io

def flatten(d, prefix=""):
    items = {}
    for k, v in d.items():
        pk = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict):
            items.update(flatten(v, pk))
        else:
            items[pk] = v
    return items

def format_cell(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return json.dumps(v)
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return json.dumps(v, separators=(",", ":"), ensure_ascii=False)
    # What if nested object reached here? Flattening removes dicts, but if any:
    return json.dumps(v, separators=(",", ":"), ensure_ascii=False)

errors = []
rows = []
all_keys = set()

with open("/data/events.jsonl", "r", encoding="utf-8") as f:
    for idx, line in enumerate(f, 1):
        if not line.strip():
            continue
        try:
            val = json.loads(line)
            if not isinstance(val, dict):
                errors.append(idx)
            else:
                flat = flatten(val)
                rows.append(flat)
                all_keys.update(flat.keys())
        except Exception:
            errors.append(idx)

columns = sorted(list(all_keys))
print("Errors:", errors)
print("Columns:", columns)
for r in rows:
    row_vals = [format_cell(r.get(c)) for c in columns]
