import json
import csv
from pathlib import Path

def flatten(d, prefix=""):
    items = {}
    for k, v in d.items():
        pk = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict):
            items.update(flatten(v, pk))
        else:
            items[pk] = v
    return items

def format_cell(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return json.dumps(v)
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return json.dumps(v, separators=(",", ":"), ensure_ascii=False)
    return json.dumps(v, separators=(",", ":"), ensure_ascii=False)

errors = []
rows = []
all_keys = set()

with open("/data/events.jsonl", "r", encoding="utf-8") as f:
    for idx, line in enumerate(f, 1):
        if not line.strip():
            continue
        try:
            val = json.loads(line)
            if not isinstance(val, dict):
                errors.append(idx)
            else:
                flat = flatten(val)
                rows.append(flat)
                all_keys.update(flat.keys())
        except Exception:
            errors.append(idx)

columns = sorted(list(all_keys))

Path("/out").mkdir(parents=True, exist_ok=True)

with open("/out/events.csv", "w", encoding="utf-8", newline="") as f:
    writer = csv.writer(f, delimiter=",", lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    writer.writerow(columns)
    for r in rows:
        writer.writerow([format_cell(r.get(c)) for c in columns])

with open("/out/errors.txt", "w", encoding="utf-8", newline="\n") as f:
    for err in errors:
        f.write(f"line {err}\n")
'

